TypeScript example (undici / fetch with Agent):

import { Agent } from 'undici'

// interactive preset
const agent = new Agent({ keepAliveTimeout: 30000, keepAliveMaxTimeout: 120000, connections: 50, pipelining: 1 })
const controller = new AbortController()
setTimeout(() => controller.abort(), 5000) // request timeout 5s
const res = await fetch(url, { signal: controller.signal, dispatcher: agent })

// hedging: manual parallel requests with first-ok wins (opt-in)
